import re

from moler.cmd.unix.genericunix import GenericUnixCommand
from moler.exceptions import ParsingDone


class FpAppDebugCountersDump(GenericUnixCommand):
    """Command fpAppDebugCountersDump."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Command fpAppDebugCountersDump.

        :param connection: moler connection to device, terminal when command is executed
        :param options: Options of fpAppDebugCountersDump command.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(FpAppDebugCountersDump, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.header = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"/opt/trs/bin/FpAppDebugCountersDump {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_header(line)
                self._parse_counter(line)
            except ParsingDone:
                pass
        return super(FpAppDebugCountersDump, self).on_new_line(line, is_full_line)

    # =======DisplayIPSecCounters======
    _re_header = re.compile(r"=+(?P<HEADER>[^=]+)=+")

    def _parse_header(self, line):
        if self._regex_helper.search_compiled(FpAppDebugCountersDump._re_header, line):
            self.current_ret[self._regex_helper.group("HEADER")] = {}
            self.header = self._regex_helper.group("HEADER")
            raise ParsingDone

    # IWF Counter dlrxpacket              43b
    _re_counter = re.compile(r"^(?P<COUNTER_NAME>([^0-9,\s]+\s?)*),?\s*(?P<VALUE>[0-9a-z]+)")

    def _parse_counter(self, line):
        if self._regex_helper.search_compiled(FpAppDebugCountersDump._re_counter, line):
            if self.header:
                self.current_ret[self.header][self._regex_helper.group("COUNTER_NAME").rstrip()] = {}
                self.current_ret[self.header][self._regex_helper.group("COUNTER_NAME").rstrip()]["raw_hex"] = self._regex_helper.group("VALUE")
                self.current_ret[self.header][self._regex_helper.group("COUNTER_NAME").rstrip()]["dec"] = int(self._regex_helper.group("VALUE"), 16)
            else:
                self.current_ret[self._regex_helper.group("COUNTER_NAME").rstrip()] = {}
                self.current_ret[self._regex_helper.group("COUNTER_NAME").rstrip()]["raw_hex"] = self._regex_helper.group("VALUE")
                self.current_ret[self._regex_helper.group("COUNTER_NAME").rstrip()]["dec"] = int(self._regex_helper.group("VALUE"), 16)
            raise ParsingDone


